def _check_unusual_fields(self, fields: dict) -> bool:
    """Check if header fields are unusual or unexpected"""
    if not isinstance(fields, dict):
        return False
    unusual_patterns = ['corrupted', 'malformed', 'zero_length']
    return any(pattern in str(fields).lower() for pattern in unusual_patterns)

def _check_invalid_values(self, field_values: dict) -> bool:
    """Check if field values are invalid or out of expected range"""
    if not isinstance(field_values, dict):
        return False
    for key, value in field_values.items():
        if value is None or (isinstance(value, (int, float)) and value < 0):
            return True
    return False

def _detect_header_anomalies(self, header_analysis):
     anomalies = []
     if not header_analysis.get('format_valid', True):
         anomalies.append('invalid_format')
     if self._check_unusual_fields(header_analysis.get('fields', {})):
         anomalies.append('unusual_fields')
     if self._check_invalid_values(header_analysis.get('field_values', {})):
         anomalies.append('invalid_values')
     return anomalies

def _analyze_file(self):
     """Analyze selected file"""
     filepath = self.file_path_var.get()
     if not filepath:
         messagebox.showwarning("No File", "Please select a file first")
         return

     if not os.path.exists(filepath):
         messagebox.showerror("File Not Found", f"File not found: {filepath}")
         return

     self._update_status(f"Analyzing {filepath}...")
     self.file_analysis_text.delete(1.0, tk.END)

     try:
         # Handle archive extraction if enabled
         analysis_files = [filepath]
         if self.extract_archive_var.get():
             temp_dir = Path("temp_analysis")
             if self.counter.binary_analyzer.archive_extractor.unpack_file(filepath, str(temp_dir)):
                 stats = self.counter.binary_analyzer.archive_extractor.get_extraction_stats()
                 self._update_status(f"Extracted {stats['successful_extractions']} files. Analyzing...")
                 # Add extracted files to analysis
                 if temp_dir.exists():
                     analysis_files.extend([f for f in temp_dir.rglob("*") if f.is_file()])

         # Analyze all files
         all_results = []
         for file_to_analyze in analysis_files:
             with open(file_to_analyze, 'rb') as f:
                 data = f.read()

             result = self.counter.generate_full_report(data)
             all_results.append({
                 'file': str(file_to_analyze),
                 'result': result
             })
